t.script:
document.addEventListener('DOMContentLoaded', function() {
    // --- QR CODE SCANNER SCRIPT ---
    function onScanSuccess(decodedText, decodedResult) {
        console.log(`Scan result (token): ${decodedText}`);

        // --- SECURITY FIX ---
        // We now expect only the access_token, not a full URL.
        // We build the URL ourselves to ensure it's on this kiosk.
        const scanUrl = `${window.location.origin}/visitor/scan/${decodedText}`;

        html5Qrcode.stop().then(ignore => {
            document.getElementById('qr-reader').innerHTML = 
                '<p style="color: var(--primary-color); padding: 20px; font-size: 18px;">Scan successful! Redirecting...</p>';
            window.location.href = scanUrl; // Use the constructed URL
        }).catch(err => {
            console.error("Failed to stop scanner", err);
            window.location.href = scanUrl; // Redirect anyway
        });
    }

    function onScanFailure(error) {
        // This will fire continuously, which is normal.
    }

    try {
        var html5Qrcode = new Html5Qrcode("qr-reader");
        const qrboxFunction = (viewfinderWidth, viewfinderHeight) => {
            let minEdgePercentage = 0.7; // 70%
            let minEdgeSize = Math.min(viewfinderWidth, viewfinderHeight);
            let qrboxSize = Math.floor(minEdgeSize * minEdgePercentage);
            return {
                width: qrboxSize,
                height: qrboxSize
            };
        }
        const config = { 
            fps: 15,
            qrbox: qrboxFunction,
            videoConstraints: {
               focusMode: "continuous"
            }
        };

        html5Qrcode.start({ facingMode: "environment" }, config, onScanSuccess, onScanFailure)
            .catch(err => {
                console.warn("Environment camera failed, trying user camera.", err);
                html5Qrcode.start({ facingMode: "user" }, config, onScanSuccess, onScanFailure)
                    .catch(err2 => {
                        console.error("Failed to start any camera.", err2);
                        document.getElementById('qr-reader').innerHTML = 
                            '<p style="color: red; padding: 20px;">Could not start camera. Please ensure permissions are granted.</p>';
                    });
            });
    } catch (ex) {
        console.error("Error initializing QR Scanner", ex);
         document.getElementById('qr-reader').innerHTML = 
            '<p style="color: red; padding: 20px;">Error initializing scanner. Please refresh.</p>';
    }
});

document.addEventListener('DOMContentLoaded', function() {
    // --- Get all steps ---
    const step1 = document.getElementById('step_1_contact');
    const step2 = document.getElementById('step_2_details');
    const step3 = document.getElementById('step_3_employee');

    // --- Get all buttons ---
    const btnCheck = document.getElementById('btn_check_visitor'); // Step 1 ->
    const btnBackToStep1 = document.getElementById('btn_back_to_step_1'); // Step 2 -> 1
    const btnToStep3 = document.getElementById('btn_to_step_3'); // Step 2 -> 3
    const btnBackFromStep3 = document.getElementById('btn_back_from_step_3'); // Step 3 -> (1 or 2)
    const btnSubmit = document.getElementById('btn_submit_walkin'); // Step 3 -> Submit

    // --- Get form fields ---
    const inputName = document.getElementById('visitor_name');
    const inputPhone = document.getElementById('visitor_phone');
    const inputEmail = document.getElementById('visitor_email');
    const inputCompany = document.getElementById('visitor_company');

    // --- Get UI elements ---
    const welcomeMsg = document.getElementById('welcome_back_message');
    const visitorNameSpan = document.getElementById('existing_visitor_name');
    const formSubtitle = document.getElementById('form_subtitle');
    const csrfToken = document.querySelector('input[name="csrf_token"]').value;

    // --- State variable ---
    let isExistingVisitor = false;

    // --- Step 1 -> Check Visitor ---
    btnCheck.addEventListener('click', function() {
        const name = inputName.value.trim();
        const phone = inputPhone.value.trim();

        if (!name || !phone) {
            alert('Please enter your full name and phone number.');
            return;
        }

        btnCheck.textContent = 'Checking...';
        btnCheck.disabled = true;

        fetch('/visitor/walkin/check', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Csrf-Token': csrfToken
            },
            body: JSON.stringify({
                name: name,
                phone: phone
            })
        })
        .then(response => {
            if (!response.ok) {
                throw new Error('Odoo Server Error. Please contact support.');
            }
            return response.json();
        })
        .then(data => {
            if (data.error) {
                let errorMessage = data.error.message || (data.error.data && data.error.data.message) || data.error;
                throw new Error(String(errorMessage));
            }

            const result = (data && data.result) ? data.result : data;

            step1.style.display = 'none';

            if (result.status === 'found') {
                // --- EXISTING VISITOR ---
                isExistingVisitor = true;
                formSubtitle.textContent = "Please confirm who you are visiting.";
                welcomeMsg.style.display = 'block';
                visitorNameSpan.textContent = result.name;

                inputEmail.value = result.email || '';
                inputCompany.value = result.company || '';

                step2.style.display = 'none';
                step3.style.display = 'block'; // Skip to Step 3

            } else if (result.status === 'not_found') {
                // --- NEW VISITOR ---
                isExistingVisitor = false;
                formSubtitle.textContent = "Welcome! Please provide a few more details.";
                welcomeMsg.style.display = 'none';
                step2.style.display = 'block'; // Go to Step 2
                step3.style.display = 'none';
            } else {
                throw new Error('Received an invalid response from the server.');
            }
        })
        .catch(err => {
            alert('An error occurred: ' + err.message);
            console.error(err);
        })
        .finally(() => {
            btnCheck.textContent = 'Next';
            btnCheck.disabled = false;
        });
    });

    // --- Step 2 -> Step 1 ---
    btnBackToStep1.addEventListener('click', function() {
        formSubtitle.textContent = "Please enter your details to check in.";
        step1.style.display = 'block';
        step2.style.display = 'none';
        step3.style.display = 'none';
    });

    // --- Step 2 -> Step 3 ---
    btnToStep3.addEventListener('click', function() {
        formSubtitle.textContent = "Please select who you are visiting.";
        step1.style.display = 'none';
        step2.style.display = 'none';
        step3.style.display = 'block';
    });

    // --- Step 3 -> (Step 1 or 2) ---
    btnBackFromStep3.addEventListener('click', function() {
        if (isExistingVisitor) {
            // Go back to step 1
            formSubtitle.textContent = "Please enter your details to check in.";
            step1.style.display = 'block';
        } else {
            // Go back to step 2
            formSubtitle.textContent = "Welcome! Please provide a few more details.";
            step2.style.display = 'block';
        }
        step3.style.display = 'none';
        welcomeMsg.style.display = 'none';
    });

    // --- Step 3 -> Submit ---
    btnSubmit.addEventListener('click', function() {
        btnSubmit.textContent = 'Submitting...';
        btnSubmit.disabled = true;
        document.getElementById('walkin_form').submit();
    });
});
